values
(E'https://matcha-jp.com/en/2563', E'en', 1, E'Shakotan Peninsula', E'The Shakotan Peninsula (積丹半島, Shakotan hantō) in Shiribeshi, on the west coast of Hokkaido, Japan, is a mountainous peninsula which projects some 30 kilometres (19 mi) into the Sea of Japan.\n\nThe Shakotan Peninsula forms part of the Niseko-Shakotan-Otaru Kaigan Quasi-National Park.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/12/13-156805.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/1636.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/04-78683.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/04-78678.webp"]'::jsonb, E'2016-11-01'::timestamptz, E'Shakotan Peninsula', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Shakotan_Peninsula'),
(E'https://matcha-jp.com/en/2597', E'en', 1, E'Mount Hakodate Ropeway', E'The Mt.Hakodate Ropeway (函館山ロープウェイ, Hakodateyama Rōpuwei) is the name of an aerial lift, as well as its operator.\n\nThe line climbs Mount Hakodate in Hakodate, Japan.As of 2004, this is the most heavily used aerial lift line in Japan, transporting 1,559,000 riders yearly.\n\n[1] The aerial tramway was prominently featured in Noein, a 2005 anime.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/06/01-55479.webp","https://resources.matcha-jp.com/resize/720x2000/2023/10/12-148451.jpeg","https://resources.matcha-jp.com/resize/720x2000/2023/10/12-148452.jpeg","https://resources.matcha-jp.com/resize/720x2000/2022/01/28-121780.webp"]'::jsonb, E'2016-10-23'::timestamptz, E'Mount Hakodate Ropeway', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Mount_Hakodate_Ropeway'),
(E'https://matcha-jp.com/en/6639', E'en', 1, E'Kanemori Red Brick Warehouses', E'The Kanemori Red Brick Warehouses (金森赤レンガ倉庫, Kanemori Akarenga Sōko) are a group of historic red brick warehouses located in Hakodate, Hokkaido, Japan.\n\n, Ltd.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/09/28-63660.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/28-63663.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/28-63664.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/28-63661.webp"]'::jsonb, E'2026-03-16'::timestamptz, E'Kanemori Red Brick Warehouses', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Kanemori_Red_Brick_Warehouses'),
(E'https://matcha-jp.com/en/3970', E'en', 2, E'Aomori Nebuta Matsuri', E'The Aomori Nebuta Matsuri (青森ねぶた祭; "Aomori Nebuta Festival" or simply "Aomori Nebuta") is a Japanese summer festival that takes place in Aomori, Aomori Prefecture, Japan in early August.\n\nThe festival attracts the most tourists of any of the country\'s nebuta festivals, and is counted among the three largest festivals in the Tōhoku region.\n\nIt was designated an Important Intangible Folk Cultural Property in 1980, and as one of the 100 Soundscapes of Japan by the Ministry of the Environment in 1996.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/04/03-23160.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/03-23157.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/03-23158.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/03-23159.webp"]'::jsonb, E'2019-04-10'::timestamptz, E'Aomori Nebuta Matsuri', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Aomori_Nebuta_Matsuri'),
(E'https://matcha-jp.com/en/23228', E'en', 2, E'Aomori Food Guide: Tsugaru Ramen, Grilled Shellfish with Miso, and More', E'This article introduces signature dishes and popular restaurants in Aomori. Surrounded by the sea, Aomori offers a wide variety of local delicacies, including Tsugaru ramen, grilled shellfish with miso, miso curry milk ramen, and more!\n\nAomori is known for its excellent local dishes such as Tsugaru Ramen, Miso Curry Milk Ramen, Oma Tuna, Grilled Shellfish with Miso, and Towada Barayaki.\n\nSurrounded by the Sea of Japan, Tsugaru Strait, and the Pacific Ocean on three sides, Aomori Prefecture features many local delicacies that utilize seafood.\n\nThis article introduces the characteristics of Aomori’s representative local dishes and popular restaurants where you can taste them.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215205.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215196.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215197.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215206.webp"]'::jsonb, E'2025-01-15'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/4255', E'en', 2, E'Cherry Blossoms in Late April! Top 15 Spots in Northern Japan', E'Discover the 15 best cherry blossom spots in Tohoku, northern Japan, for 2026, with our updated bloom forecast and travel guide for Aomori, Morioka, Kakunodate, and other iconic locations.\n\nCherry blossom forecast map created based on information released by JMC\n\nThe Tohoku region refers to the six prefectures in the northern part of Japan\'s Honshu Island: Aomori, Iwate, Miyagi, Akita, Yamagata, and Fukushima.\n\nDue to its location at a higher latitude, the cherry blossoms in Tohoku bloom a little later than in Tokyo, usually from early April to late May each year.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/03/02-260098.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/07-94518.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/07-94519.webp","https://resources.matcha-jp.com/resize/720x2000/2024/03/28-175574.webp"]'::jsonb, E'2024-04-16'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/7375', E'en', 3, E'Iwate Travel Guide: 18 Places to Visit, Food, Scenic Sites', E'Iwate is best known for the World Heritage Sites of Chusonji Temple and Motsuji Temple. It also boasts stunning nature such as the Geibikei and Genbikei gorges. Enjoy them with its delicious local cuisine, such as Wanko Soba and fresh seafood from the Pacific Ocean.\n\nIwate, located in the Tohoku region in northern Japan, is the country\'s second largest prefecture and famous for its breathtaking natural scenery.\n\nMorioka, one of the largest cities in Iwate, can be reached by Shinkansen from Tokyo in 2 hours and 13 minutes.\n\nIwate boasts World Heritage sites that date back to the era when the Fujiwara clan ruled the Tohoku region during the 12th century. The famous Japanese folklorist, Kunio Yanagita, wrote folk tales while in Iwate.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/10-76564.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/10-76566.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/10-76565.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/10-76568.webp"]'::jsonb, E'2019-06-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/7874', E'en', 3, E'Iwate Food Guide - Delicious Seafood, Noodles, Wagyu Beef, And Sweets', E'Iwate, one of the venues of the Rugby World Cup Japan 2019™️, has no shortage of tasty cuisine. We\'ve compiled a list of classic favorites such as local noodle dishes, seafood, and wagyu beef, all the way to craft beers and delicious sweets.\n\nIwate, a prefecture in the Tohoku Region, is brimming with a variety of delicious dishes!\n\nThough Iwate is famous for unique fare such as The Three Great Noodle Dishes of Morioka, visitors can enjoy the bounty of both the sea and the mountains as the prefecture\'s east side faces the Pacific Ocean and is also home to Mt. Iwate and Mt. Hachimantai. Of course, you can\'t overlook the delicious craft beers and sweets here, too.\n\nIwate is also one of the venues hosting the Rugby World Cup Japan 2019™️ (from here on referred to as the World Cup).', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/18-86335.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/08-85516.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/08-85517.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/08-85519.webp"]'::jsonb, E'2019-09-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/7824', E'en', 3, E'Kamaishi Recovery Memorial Stadium', E'a.the Kamaishi Unosumai Stadium, is a stadium in Unosumai-cho, Kamaishi, Iwate.\n\nConstruction on the 16,187-seat venue broke ground in April 2017 and it was completed on 19 August 2018.\n\nIt hosted one pool match during the 2019 Rugby World Cup, with another scheduled match that was cancelled due to Typhoon Hagibis.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/08/23-84426.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/23-84427.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/23-84431.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/23-84430.webp"]'::jsonb, E'2019-09-09'::timestamptz, E'Kamaishi Recovery Memorial Stadium', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Kamaishi_Recovery_Memorial_Stadium'),
(E'https://matcha-jp.com/en/3535', E'en', 4, E'Sakunami Onsen', E'Sakunami Onsen (作並温泉) is a hot spring resort district in northern Japan about 25 kilometres (16 mi) to the northwest of downtown Sendai, Miyagi Prefecture.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/02/15-71440.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/20-73467.webp","https://resources.matcha-jp.com/resize/720x2000/2016/11/23-10025.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/25-73736.webp"]'::jsonb, E'2017-01-03'::timestamptz, E'Sakunami Onsen', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Sakunami_Onsen'),
(E'https://matcha-jp.com/en/7757', E'en', 4, E'Naruko Dam', E'Naruko Dam (Japanese: 鳴子ダム, Naruko Damu) is a concrete gravity-arch dam on the Eaigawa River, a tributary of the Kitakami River system, located in the city of Ōsaki, Miyagi Prefecture, Japan.\n\nCompleted in 1958 by Kajima Corporation, it is managed by the Tohoku Regional Development Bureau of the Ministry of Land, Infrastructure, Transport and Tourism.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/10/23-88826.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/23-88825.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/26-86756.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/21-88753.webp"]'::jsonb, E'2019-11-09'::timestamptz, E'Naruko Dam', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Naruko_Dam'),
(E'https://matcha-jp.com/en/23552', E'en', 4, E'Sendai Cherry Blossom Guide: 8 Scenic Spots in 2026', E'Sendai is home to many famous cherry blossom spots, including Nishi Park and the Sendai Castle Ruins. Discover eight iconic locations.\n\nCherry blossom forecast map created based on information released by JMC\n\nKnown as the "City of Trees," Sendai is surrounded by lush greenery. The city is also home to numerous famous cherry blossom spots.\n\nIn 2026, the cherry blossoms in Sendai are expected to start blooming around April 4 and reach full bloom around April 9. (Source: JMC Sakura Forecast)', E'["https://resources.matcha-jp.com/resize/720x2000/2026/03/02-260098.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/17-219608.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/14-219106.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/14-219107.webp"]'::jsonb, E'2025-01-22'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/3183', E'en', 5, E'Northern Japan in Autumn: 15 Fall Foliage Spots in 2025', E'In northern Japan, the fall foliage can be enjoyed earlier than Tokyo and Kyoto - from around mid-October. Learn the best 15 fall spots in Sendai, Aomori, Lake Towada, Fukushima, and other areas in Tohoku.\n\n2025 fall foliage map based on information from Weathernews\n\nThe Tohoku region, which encompasses six prefectures in the northeastern part of Japan\'s Honshu Island, is home to both magnificent natural scenery and historical structures.\n\nShirakami-Sanchi—a World Heritage Site in Aomori, Lake Towada, and the countless cultural heritage sites in Iwate\'s Hiraizumi are very beautiful in the fall.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/10/07-246219.webp","https://resources.matcha-jp.com/resize/720x2000/2023/07/29-142187.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/01-82825.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/01-82751.webp"]'::jsonb, E'2019-04-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/4198', E'en', 5, E'Akita Kanto Festival 2026: a Parade of 10,000 Lanterns', E'The Akita Kanto Festival is held August 3-6 to pray for health and a good harvest. Check the dates and highlights to witness 10,000 lanterns fill the night sky.\n\nThe Akita Kanto Matsuri, or Akita Kanto Festival is an annual festival held in summer in Akita City, northern Japan.\n\nTogether with the Nebuta Festival in Aomori, and the Tanabata Festival in Sendai, it is considered to be one of the Three Great Tohoku Festivals, and it certainly is one magnificent festival the Tohoku region is proud of.\n\nIt is believed that the origins of the Akita Kanto Festival could be tracked down to the old custom of neburi nagashi, often performed during the Tanabata, Obon, and other festivals of the old Japanese calendar (*1).', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21813.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21814.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21810.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21809.webp"]'::jsonb, E'2017-07-24'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/25099', E'en', 5, E'[Akita] With over 100 years of history! Japan\'s No. 1 fireworks competition - "Omagari Fireworks Festival"', E'The Omagari Fireworks Festival is one of Japan\'s leading fireworks festivals, held annually in Daisen City (formerly Omagari City), Akita Prefecture. This festival has a long history of over 100 years. It is known as "Japan\'s No. 1 fireworks competition" due to its technical skill and high level of prestige.\n\nThe origins of this event date back to 1910 (Meiji 43), and it is a historic and prestigious event that has been handed down for over 100 years since then. Today, it is highly regarded as Japan\'s most prestigious fireworks competition, where top fireworks makers selected from around the country gather to compete in skill and artistry.\n\nThe biggest feature of Omagari Fireworks is that the fireworks are not just for viewing, but are positioned as a "competition." Only a select few fireworks companies can participate, and all the fireworks that are launched boast an extremely high level of perfection in terms of composition, color, timing, and creativity.\n\nThe event is divided into "Daytime Fireworks" and "Night Fireworks." The daytime fireworks feature a visual and technical display using the colors and shapes of the smoke.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/06/06-235675.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/06-235676.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/06-235678.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/06-235680.webp"]'::jsonb, E'2025-06-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/25347', E'en', 6, E'Yonezawa in Yamagata: A 1-Night, 2-Day Itinerary Packed with Gourmet Eats, Nature & Onsen', E'In this article, we’ll introduce the best spots you can visit on a 1-night, 2-day trip to Yonezawa, while sharing the hidden charms of this city in Yamagata Prefecture.\n\nYonezawa City in Yamagata Prefecture is famous as a castle town with beautiful scenery throughout the four seasons. Although it is a historic town with ties to the Sengoku period warlords Uesugi Kenshin and Uesugi Yozan, there is also a wealth of attractions in various places, such as the delicious gourmet food of Yonezawa beef, Onogawa Onsen, where fireflies flutter about in season, and Tengendai Takaharu , where you can enjoy nature to the fullest. Yonezawa City, Yamagata Prefecture , can be reached from Tokyo in about two hours on the Yamagata Shinkansen. This time, we will introduce recommended spots to visit in aa 1-night, 2-day to make the most of your time in Yonezawa City . I hope that through this article you will be able to get a sense of the charms of Yonezawa City, Yamagata Prefecture that you may not yet know about. In this article, we will be focusing on gourmet food, stunning views, and hot springs.\n\nThere are rental cars, tourist buses, and taxis available near the station, so you can still enjoy sightseeing even if you can\'t drive. It would also be nice to rent a bicycle and go sightseeing, especially in spring and autumn.\n\nWhen sightseeing in Yonezawa City, we recommend renting a bicycle depending on the weather. There are three locations in the city where you can rent a bicycle: Yonezawa Station, Uesugi Count\'s Residence (Japanese Garden), and Yonezawa Roadside Station. You can also return the car anywhere between Yonezawa Station and the Uesugi Count\'s Residence (Japanese Garden), so it\'s great that you can use the service to suit your travel style. In addition, the rental bicycles are electric, making it easy to get around. Although the number is limited, some come with child seats, so you can consider renting one with small children.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238260.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238282.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238278.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238279.webp"]'::jsonb, E'2025-07-08'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/17723', E'en', 6, E'Zao Onsen Guide: Ski Resorts, Snow Monsters, and Hot Springs', E'The Zao region, nestled between Miyagi and Yamagata prefectures, offers natural marvels like the snow monsters, ancient hot springs, a fox village, and the volcanic crater lake Okama. This nature-rich paradise is ideal for outdoor enthusiasts with hiking and skiing opportunities.\n\nZao is located on the border of Yamagata and Miyagi prefectures in the Tohoku region. In recent years, it has gained popularity due to the snow monsters (juhyo) and Zao Fox Village being prominent tourist spots.\n\nIn addition to these two attractions, the Zao area in Yamagata, known for its hot springs, has nature-rich surroundings worth exploring. You can also climb an active volcano and see the volcanic crater lake known as Okama. In winter, there are excellent ski resorts to enjoy as well.\n\nHow to Get to Zao The main attractions in Zao are centered around Zao Onsen. To reach Zao Onsen, you must take a bus to Zao Onsen Bus Terminal. The bus ride from JR Yamagata Station takes about 40 minutes.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/08/18-241571.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/23-111130.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/24-61276.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/27-159998.webp"]'::jsonb, E'2024-01-18'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/8000', E'en', 6, E'Yamagata Top 15 Things To Do - Ginzan Onsen, Mt. Zao, Yamadera, And More', E'Yamagata Prefecture in northern Japan is filled with exciting destinations, including retro onsen towns, frost-covered trees of Mt. Zao, and local delicacies from wagyu beef, ramen, to sake. Learn the top sightseeing spots in Yamagata and how to get there.\n\nYamagata Prefecture is located in the southern part of Japan\'s Tohoku region and faces the Sea of Japan.\n\nThe prefecture has scenic mountain and ocean views with hot springs steeped with history and culture. It\'s also where visitors can enjoy regional food and drink, including fruit, wagyu beef, ramen, and locally brewed sake.\n\nYamagata Prefecture has four main regions. The Murayama region is home to prefectural capital, Yamagata city, which boasts spring towns such as Ginzan Onsen and Zao Onsen, and delicious cherries. The Okitama region is known for its Yonezawa beef, a type of wagyu Japanese beef, among other tasty foods.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/30-87052.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/30-87056.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/30-87087.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/30-87086.webp"]'::jsonb, E'2019-10-15'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/24299', E'en', 7, E'Aizuwakamatsu Castle', E'Tsuruga Castle (鶴ヶ城, Tsuru-ga-jō), also known as Aizuwakamatsu Castle (会津若松城 Aizu-Wakamatsu-jō) is a Japanese castle in northern Japan, at the center of the city of Aizuwakamatsu, in Fukushima Prefecture.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226232.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226234.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226233.webp","https://resources.matcha-jp.com/resize/720x2000/2025/12/26-254092.webp"]'::jsonb, E'2025-03-11'::timestamptz, E'Aizuwakamatsu Castle', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Aizuwakamatsu_Castle'),
(E'https://matcha-jp.com/en/23836', E'en', 7, E'Fukushima: 10 Scenic Cherry Blossom Spots to Visit in 2026', E'Fukushima Prefecture is dotted with many famous cherry blossom spots. We introduce 10 famous cherry blossom locations in Fukushima―from classic spots all the way to hidden gems.\n\nFukushima Prefecture, blessed with an abundance of natural surroundings, is dotted with some of Japan\'s best cherry blossom viewing spots.\n\nHowever, the media tends to focus exclusively on famous places such as the Meguro River (Tokyo) and Hirosaki Park (Aomori Prefecture). Visitors from outside Fukushima might not be familiar with the famous cherry blossom spots the region has to offer.\n\nSo this article introduces Fukushima\'s top 10 cherry blossom viewing locations, from classic spots all the way to little-known hideaways.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/31-221833.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/31-221835.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/31-221839.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/31-221844.webp"]'::jsonb, E'2025-02-07'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/7443', E'en', 7, E'10 Things to Do in Fukushima: Sightseeing, Food, and Safety', E'Fukushima is filled with wonderful spots for travel, like Aizu Wakamatsu, Ouchijuku, Lake Inawashiro, and the Tadami Line. Read to learn about where to visit, activities, and local food. This article also introduces tips, from transportation to the latest safety information.\n\nFukushima is a prefecture located in the northern Tohoku region of Japan. With its great outdoors, delicious cuisine, and seasonal views, it is an ideal spot for you to visit again and again.\n\nSince the incidents in 2011, Fukushima is now completely safe for visitors to travel in nearly all parts of Fukushima Prefecture.\n\nIn this article, we introduce the latest information on Fukushima, along with must-visit spots, cultural events, and delicious food.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/22-77516.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/21-77424.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/20-77305.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/21-77432.webp"]'::jsonb, E'2019-06-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/25326', E'en', 8, E'[Kanto area] Let\'s go see the autumn kochia! 4 popular spots we definitely recommend🍁', E'Autumn is the season when the beauty of nature is particularly striking. The temperature becomes mild and the air is clear and comfortable, making it the perfect time for outings and walks. The autumn leaves color the mountains, and the unique autumn scenery soothes our souls.\n\nAutumn is known as a season that offers many different ways to enjoy it. The temperature becomes milder and the air becomes clearer, making it the perfect time for outings and walks. The mountains change color and the beauty of nature is considered to be the most striking season of the year.\n\nOne plant you can\'t miss in the fall is "kochia," an annual plant known in Japanese as "hokigusa."\n\nKochia is an annual plant of the Bassia genus in the Amaranthaceae family, and its Japanese name is "hokigusa." The name comes from the fact that mature stems were dried and used as brooms in the past. Kochia is characterized by its unique round and fluffy shape, making it a very cute looking plant.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238066.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238089.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238068.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238069.webp"]'::jsonb, E'2025-07-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/22139', E'en', 8, E'Mount Tsukuba Autumn Foliage: Best Spots and Fall Festivals', E'Discover Mount Tsukuba’s autumn foliage in November. Enjoy scenic hikes, cable car rides, and the Tsukuba Momiji Festival during peak fall season.\n\nMount Tsukuba, located in Ibaraki is one of the best places to enjoy hiking amid autumn foliage near Tokyo.\n\nTsukuba Station can be reached in about 40 minutes by train from Akihabara Station on the Tsukuba Express Line. From the station, you can go by local bus to the Mount Tsukuba entrance in about 20 minutes.\n\nThe ideal time to see the autumn foliage on Mount Tsukuba is typically from early to late November, with stunning scenery spreading from the summit down to the foothills.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/24-204865.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/24-204866.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/28-205698.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/24-204867.webp"]'::jsonb, E'2024-10-24'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/11536', E'en', 8, E'Hitachi Seaside Park', E'Hitachi Seaside Park (国営ひたち海浜公園, Kokuei Hitachi Kaihinkōen) is a public park in Hitachinaka, Ibaraki, Japan.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/23-77620.webp","https://resources.matcha-jp.com/resize/720x2000/2019/01/10-69160.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/18-133844.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/26-39710.webp"]'::jsonb, E'2023-05-09'::timestamptz, E'Hitachi Seaside Park', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Hitachi_Seaside_Park'),
(E'https://matcha-jp.com/en/22758', E'en', 9, E'Tochigi Prefectural Museum of Fine Arts', E'Tochigi Prefectural Museum of Fine Arts (栃木県立美術館, Tochigi Kenritsu Bijutsukan) opened in Utsunomiya, Tochigi Prefecture, Japan, in 1972.\n\nThe collection includes works by Hamada Shōji, Takahashi Yuichi, Constable, Corot, Gainsborough, Monet, and Turner, and special exhibitions are also mounted.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/19-210042.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/19-210043.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/19-210044.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/19-210045.webp"]'::jsonb, E'2024-12-02'::timestamptz, E'Tochigi Prefectural Museum of Fine Arts', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Tochigi_Prefectural_Museum_of_Fine_Arts'),
(E'https://matcha-jp.com/en/7516', E'en', 9, E'Tochigi Prefectural Museum of Fine Arts', E'Tochigi Prefectural Museum of Fine Arts (栃木県立美術館, Tochigi Kenritsu Bijutsukan) opened in Utsunomiya, Tochigi Prefecture, Japan, in 1972.\n\nThe collection includes works by Hamada Shōji, Takahashi Yuichi, Constable, Corot, Gainsborough, Monet, and Turner, and special exhibitions are also mounted.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78884.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/05-78785.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78880.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/05-78780.webp"]'::jsonb, E'2019-06-25'::timestamptz, E'Tochigi Prefectural Museum of Fine Arts', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Tochigi_Prefectural_Museum_of_Fine_Arts'),
(E'https://matcha-jp.com/en/5412', E'en', 9, E'Edo Wonderland Nikko Edomura: 10 Activities to Enjoy in Day', E'Edo Wonderland Nikko Edomura is a cultural theme park near Nikko that recreates the atmosphere of Edo (pre-modern Tokyo). Become an Edo citizen for a day and explore the roots of Japanese culture through the amazing activities available in Edo Wonderland.\n\nAnyone planning a trip to Japan who did a bit of research on what to visit in Nikko must have heard of Edo Wonderland, an area that recreates the atmosphere of Edo (pre-modern Tokyo).\n\nAlso known as Nikko Edomura, Edo Wonderland is a samurai and ninja cultural theme park with museums, theaters, dining places, and many other facilities where visitors can have a firsthand experience of how people in Japan used to live during the Edo period (1603 - 1868).\n\nIn Edo Wonderland, you are encouraged to become an Edo citizen for a day! There is no better way to learn about the roots of Japanese culture while having fun! This article will introduce some of the activities that would make your day in Edo unforgettable.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/11/26-42260.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/26-42259.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/28-42367.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/26-42261.webp"]'::jsonb, E'2018-03-19'::timestamptz, E'Edo Wonderland Nikko Edomura', null, null),
(E'https://matcha-jp.com/en/7337', E'en', 10, E'Kusatsu Onsen', E'Kusatsu Onsen (草津温泉) is a hot spring resort located in Gunma Prefecture, Japan, northwest of Tokyo.\n\nIt is a popular tourist destination.There are 13 public baths at Kusatsu Onsen.\n\nThe small bathhouses that are free for both town residents and tourists are managed by the townspeople themselves.\n\nThe source of its hot water is nearby Mount Kusatsu-Shirane and the appearance of the waters range from cloudy to clear, because the sources of the water that the baths rely upon are different.The springs were known as a resort for centuries, but they became well known after the water was recommended for its health benefits by Erwin von Bälz, a German doctor who taught medicine at Tokyo University.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/11/10-151777.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/1949.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/24-75961.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/09-76485.webp"]'::jsonb, E'2019-05-28'::timestamptz, E'Kusatsu Onsen', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Kusatsu_Onsen'),
(E'https://matcha-jp.com/en/4040', E'en', 10, E'Minakami Onsen: Best Hot Springs, Top Ryokan and Things to Do', E'Minakami Onsen is a hot spring resort in Gunma Prefecture, which can be easily reached from Tokyo in about one hour by train. An ideal destination for a day trip, it has amazing hot springs and Japanese-style inns, which we introduce here.\n\nIn recent years, there has been a growing number of activities that take advantage of the natural spots found in this region. Tone River, a river that runs along the side of Minakami where the hot springs are clustered, is a river where you can take part in rafting and canoeing. Along with the nine ski resorts here where you can ski and snowboard in winter, this is a town that has the perfect environment for everybody from kids to adults to be able to enjoy the outdoors.\n\nThe quality of water in the hot springs is different in every bath. The most notable quality of water at Minakami Onsen is the calcium sulfate spring. A calcium spring is said to be good for treating bruises and cuts, wounds such as burns, and even breakouts of acne and rashes on the skin. These waters are clear and colorless.\n\nFor those coming from Tokyo, it’s best to take the JR Joetsu shinkansen. From Tokyo Station, get on the Joetsu Toki shinkansen headed for Niigata and get off at Jomokogen Station. It takes about an hour and 10 minutes, and costs 5390 yen.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/02/15-18743.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/15-18744.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/15-18746.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/15-18747.webp"]'::jsonb, E'2017-11-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/11938', E'en', 10, E'Kusatsu Onsen', E'Kusatsu Onsen (草津温泉) is a hot spring resort located in Gunma Prefecture, Japan, northwest of Tokyo.\n\nIt is a popular tourist destination.There are 13 public baths at Kusatsu Onsen.\n\nThe small bathhouses that are free for both town residents and tourists are managed by the townspeople themselves.\n\nThe source of its hot water is nearby Mount Kusatsu-Shirane and the appearance of the waters range from cloudy to clear, because the sources of the water that the baths rely upon are different.The springs were known as a resort for centuries, but they became well known after the water was recommended for its health benefits by Erwin von Bälz, a German doctor who taught medicine at Tokyo University.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/06/05-138956.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/06-138998.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/06-138999.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/06-139006.webp"]'::jsonb, E'2023-05-27'::timestamptz, E'Kusatsu Onsen', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Kusatsu_Onsen'),
(E'https://matcha-jp.com/en/7527', E'en', 11, E'Hikawa Shrine', E'Hikawa Shrine (氷川神社, Hikawa-jinja) is a Shinto shrine located in Ōmiya-ku, Saitama, Saitama Prefecture, Japan.\n\nIt is one of the two shrines claiming the title of ichinomiya of former Musashi Province.\n\nThe main festival of the shrine is held annually on August 1.\n\nThe district of Omiya, literally "Great Shrine", derives from the special favor shown by Emperor Meiji, who raised Hikawa above all other shrines in the Kantō region.It is the head of a network of approximately 280 Hikawa shrines mostly around the Kantō region.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/06/10-79061.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/10-79065.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/10-79066.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/10-79067.webp"]'::jsonb, E'2023-10-26'::timestamptz, E'Hikawa Shrine', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Hikawa_Shrine_(Saitama)'),
(E'https://matcha-jp.com/en/8676', E'en', 11, E'Chichibu distillery', E'Chichibu distillery (Japanese: 秩父蒸溜所, Hepburn: Chichibu jōryūsho) is a Japanese whisky distillery located in Chichibu (秩父市, Chichibu-shi), Saitama Prefecture, Japan.\n\n, the distillery was established in 2007 and began production in 2008.\n\nIt is one of three distilleries owned by Venture Whisky, whose principal brand is Ichiro\'s Malt.\n\n, the Akuto family\'s company, until its sale that year, as well as to eventually produce whisky at a distillery of its own.This plan later took shape as the Chichibu Distillery.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/05/26-138581.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/26-138582.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/26-138577.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21799.webp"]'::jsonb, E'2023-05-16'::timestamptz, E'Chichibu distillery', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Chichibu_distillery'),
(E'https://matcha-jp.com/en/26901', E'en', 11, E'Where to See Moss Phlox: 5 Top Shibazakura Spots in Japan', E'Experience the vibrant pink carpets of Japan’s moss phlox season. Discover five shibazakura locations, from a Mt. Fuji resort to hidden gems near Tokyo.\n\nOf all Japan\'s spring blooms, shibazakura (moss phlox) is a favorite for the vibrant, carpet-like landscapes it creates.\n\nLiterally translating to "lawn cherry blossoms," moss phlox flowers begin to bloom just as the traditional cherry blossom season fades, painting hillsides in shades of pink from April to May.\n\nFrom the iconic Fuji Shibazakura Festival near Mt. Fuji to hidden gems closer to Tokyo, here are five locations perfect for capturing that flawless shot.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/03/06-260524.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/06-260525.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/06-260526.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/13-260984.webp"]'::jsonb, E'2026-03-04'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/7713', E'en', 12, E'Tokyo Disneyland', E'Tokyo Disneyland (Japanese: 東京ディズニーランド, Hepburn: Tōkyō Dizunīrando; local nickname TDL) is a 126-acre (51 ha) theme park at the Tokyo Disney Resort in Urayasu, near Tokyo in Chiba Prefecture, Japan Its main gate is directly adjacent to both Maihama Station and Tokyo Disneyland Station.\n\nIt was the first Disney park to be built outside the United States and it opened on April 15, 1983.\n\nThe park was constructed by WED Enterprises in the same style as Disneyland in California and Magic Kingdom in Florida.\n\nIt is owned by the Oriental Land Company, which licenses intellectual property from the Walt Disney Company.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/07/25-82318.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/25-82302.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/24-82193.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/24-82194.webp"]'::jsonb, E'2019-07-24'::timestamptz, E'Tokyo Disneyland', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Tokyo_Disneyland'),
(E'https://matcha-jp.com/en/27369', E'en', 12, E'Narita Gion Festival: 5 Must-See Highlights and Experience Tour', E'Discover the Narita Gion Festival near Tokyo! Explore 5 must-see highlights and an immersive experience tour that lets you join the floats firsthand.\n\nHeld every year over a weekend in early July, the Narita Gion Festival boasts more than 300 years of history. As one of Chiba’s most iconic summer events, it draws roughly 450,000 visitors annually, transforming the entire temple town with electrifying energy and passion.\n\nSpanning three days, the festival comes alive with traditional music, lively dancing, and ornate floats, all driven by the intense energy of its participants.\n\nDeeply rooted in historic Japanese culture, the celebration unfolds in downtown Narita—just minutes from Narita Airport—making it an unmissable stop for international travelers.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/07/21-267470.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/21-267578.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/21-267474.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/21-267466.webp"]'::jsonb, E'2026-07-27'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/24409', E'en', 12, E'Near Tokyo! Sakura Tulip Festa 2025: Highlights and Photogenic Spots', E'The Sakura Tulip Festival 2025 will be held in April in Sakura City, near Tokyo. This event will feature highlights such as the Windmill Festival, sightseeing boats on Lake Inbanuma, and gourmet food. We\'ll also explain details on traffic restrictions for the event day.\n\nThe venue is held at Sakura Hometown Square (Sakura Furusato Plaza). It\'s famous for its tulips in April, sunflowers in July, and cosmos in October. Additionally, the windmill located within the park is a popular spot for Instagram photos.\n\nIn this article, we will introduce the highlights, event information, and access details for the Sakura Tulip Festival 2025.\n\nThe windmill at Sakura Hometown Square was built in 1994 to celebrate the 40th anniversary of Sakura City.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/03/11-227562.webp","https://resources.matcha-jp.com/resize/720x2000/2025/03/11-227563.webp","https://resources.matcha-jp.com/resize/720x2000/2025/03/11-227564.webp","https://resources.matcha-jp.com/resize/720x2000/2025/03/12-227750.webp"]'::jsonb, E'2025-03-24'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/204', E'en', 13, E'Kagurazaka', E'Kagurazaka (神楽坂) is a neighbourhood in Tokyo northwest of Iidabashi Station.\n\nIt has a shopping street at its center, lined by numerous cafés and restaurants.\n\nIt is served by Tokyo Metro Tozai Line and Toei Oedo Line.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/07/11-140972.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/04-57704.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/04-57703.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/04-57702.webp"]'::jsonb, E'2014-06-14'::timestamptz, E'Kagurazaka', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Kagurazaka'),
(E'https://matcha-jp.com/en/27200', E'en', 13, E'Tokyo\'s Adachi Fireworks Festival 2026: Date, Highlights, Tips', E'Tokyo\'s Adachi Fireworks Festival will be held on May 30! Get essential details on the 13,000-shot show near Kitasenju Station, with access and tips.\n\nFireworks are a quintessential highlight of summer in Japan, traditionally held along rivers or coastlines. Kickstarting Tokyo\'s fireworks season is the Adachi Fireworks Festival, held along the Arakawa River near Kitasenju Station.\n\nWhile historically held in July, the event was moved to late May to protect spectators from heatstroke. Read on to discover this year’s schedule, event highlights, and essential tips for avoiding post-show crowds.\n\nThe Adachi Fireworks Festival began more than a century ago, with its oldest official record dating back to the celebration of Japan\'s victory in the Russo-Japanese War in 1905.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/05/12-263957.webp","https://resources.matcha-jp.com/resize/720x2000/2026/05/12-263955.webp","https://resources.matcha-jp.com/resize/720x2000/2026/05/13-263970.webp","https://resources.matcha-jp.com/resize/720x2000/2026/05/13-263969.webp"]'::jsonb, E'2026-05-18'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/27030', E'en', 13, E'Experience Otaku Culture in Just 3 Hours! A Complete Guide to Akihabara Anime & Game Adventure Tour', E'This article introduces a popular guided tour that allows you to fully experience Akihabara\'s anime and game culture in about three hours. It efficiently takes you to maid cafes, retro games, gachapon (capsule toy) experiences, and more, making it a safe and enjoyable experience even for first-timers.\n\nTable of Contents What is the Akihabara Anime & Game Adventure Tour? Tour itinerary details Recommended for people like this For your Tokyo trip, consult TripToJapan! What is the Akihabara Anime & Game Adventure Tour? Explore the vibrant streets of Akihabara. Known as Tokyo\'s famous anime and game district, this area offers arcades, unique shops, and an authentic maid café experience. Discover hidden gems and immerse yourself in the world of unique Japanese pop culture.\n\n• A guided walking tour lasting approximately 3 hours.\n\n• Popular with foreigners as it includes an English-speaking guide.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/04/16-262788.webp","https://resources.matcha-jp.com/resize/720x2000/2026/04/16-262790.webp","https://resources.matcha-jp.com/resize/720x2000/2026/04/16-262797.webp","https://resources.matcha-jp.com/resize/720x2000/2026/04/16-262789.webp"]'::jsonb, E'2026-04-16'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/1519', E'en', 14, E'Enoshima', E'5 mi) in circumference, at the mouth of the Katase River which flows into the Sagami Bay of Kanagawa Prefecture, Japan.\n\nAdministratively, Enoshima is part of the mainland city of Fujisawa, and is linked to the Katase section of that city by a 389-metre-long (1,276 ft) bridge.\n\nHome to some of the closest sandy beaches to Tokyo and Yokohama, the island and adjacent coastline are the hub of a local resort area.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/04/18-125790.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/18-125791.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/18-125792.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/18-125793.webp"]'::jsonb, E'2016-03-17'::timestamptz, E'Enoshima', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Enoshima'),
(E'https://matcha-jp.com/en/2591', E'en', 14, E'Minato Mirai 21', E'g."MM 1"), is the central business district of Yokohama, Japan.\n\nInitially developed in the 1980s, Minato Mirai 21 was designed as a large master-planned development and new urban center planned to connect Yokohama\'s traditionally important areas and commercial centers of Kannai and the Yokohama Station area.\n\nToday, Minato Mirai is a major center for business, shopping, and tourism, attracting visitors and businesspersons throughout the Greater Tokyo Area.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/06/30-140312.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/30-140326.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/28-140051.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/30-140336.webp"]'::jsonb, E'2016-10-01'::timestamptz, E'Minato Mirai 21', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Minato_Mirai_21'),
(E'https://matcha-jp.com/en/25049', E'en', 14, E'THE OUTLETS SHONAN HIRATSUKA Guide: Shopping, Outlet Appliances, and Local Flavors', E'THE OUTLETS SHONAN HIRATSUKA is an outlet mall where you can experience the local charm of Shonan, with electronics stores, a park, a gorgeous view of Mt. Fuji, and local gourmet. Read on for an in-depth look at what it has to offer.\n\nPlanning to trip outside of Tokyo? It’s always nice to find a place where you can enjoy both shopping and the unique charm of the area. THE OUTLETS SHONAN HIRATSUKA, a new shopping complex developed by the AEON Group, offers just that.\n\nTHE OUTLETS SHONAN HIRATSUKA offers a wide variety of brands, with a stunning view of Mt. Fuji, local gourmet food, and a grassy plaza where children can play freely.\n\nNow, we’ll take a closer look at what THE OUTLETS SHONAN HIRATSUKA has to offer.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/06/02-235061.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/02-235062.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/02-235063.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/02-235064.webp"]'::jsonb, E'2025-06-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/7341', E'en', 15, E'Niigata Travel Guide: 15 Must-Visit Places, Food, And Amazing Photo Spots', E'Niigata extends north to south facing the Sea of Japan. Visitors love it for its delicious rice, sake, and seafood, along with its ski resorts and many breathtaking views. This guide introduces Niigata foods, fun activities and photogenic places within the prefecture.\n\nNiigata is a treasure trove of amazing sights and regional cuisine. Renowned as Japan’s leading producer of top-notch rice and Japanese sake, you can also expect to eat amazing seafood here because Niigata Prefecture overlooks the Sea of Japan.\n\nNiigata is located in the Chubu region of Japan\'s main island Honshu. Stretching long and thin from north to south, the prefecture is largely split into three areas starting from the west called Joetsu, Chuetsu, and Kaetsu, respectively.\n\nThere are direct flights operating from Taiwan Taoyuan International Airport to Niigata Airport, making it easily accessible for overseas visitors. For those traveling by train, it takes about two hours via the shinkansen (bullet train) from JR Tokyo Station to Niigata Station, which also makes it convenient to visit while traveling through Japan.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/08-76424.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/08-76401.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/08-76399.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/08-76400.webp"]'::jsonb, E'2019-05-26'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/25331', E'en', 15, E'[Kanto Autumn Foliage] Autumn travel season has arrived! Stunning autumn spots to visit around the Kanto region', E'With the arrival of autumn, the mountains and parks around the Kanto region are colored with beautiful autumn leaves. October is especially good for viewing the red and yellow leaves, and many people visit to enjoy the vibrant natural scenery.\n\nIn Japan, mountains and roadside trees turn red and yellow in autumn, and the custom of "momijigari" has been popular since ancient times. Along with cherry blossom viewing in spring, enjoying autumn leaves is an important part of culture to feel the change of seasons. In particular, from October to November, when maple and ginkgo trees take on beautiful colors, many people visit famous autumn foliage spots and are soothed by the beauty of nature. It is also a popular destination for travel and day trips, and temples, shrines, parks, and mountain areas are often illuminated and have events.\n\nAutumn leaves are not just a beautiful sight, but an important seasonal feature that allows Japanese people to "savor autumn."\n\nBy the way, do you know the difference between "momiji" and "momiji (maple)"? These two words are often used interchangeably, but in fact they each have a different meaning.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238244.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238115.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238116.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238117.webp"]'::jsonb, E'2025-07-07'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/22718', E'en', 15, E'Niigata Ski Guide: 11 Ski Resorts Where Even Beginners Can Have Fun!', E'In this article, we feature 11 ski resorts in the Yuzawa area of Niigata with good access from Tokyo. Families with kids and novice skiers can all have fun at unique resorts that also offer night skiing. Please refer to this article as you anticipate the upcoming ski season!\n\nNiigata Prefecture\'s Yuzawa Town is an area with great access from the Kanto Region. The Kan\'etsu Expressway\'s Yuzawa Interchange (IC) and the Joetsu shinkansen\'s Echigo Yuzawa Station are both nearby.\n\nThe region is also well known for its excellent snow quality which attracts many skiers. Many of the area\'s ski hills also offer lift tickets at reasonable prices.\n\nThis article features eleven noteworthy ski resorts from the many found in this area.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/18-209946.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/18-209947.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/18-209950.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/18-209966.webp"]'::jsonb, E'2024-11-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/9722', E'en', 16, E'Tateyama Kurobe Alpine Route Guide - Bask In Japan\'s Great Outdoors', E'The Tateyama Kurobe Alpine Route is a mountainous destination spanning 3,000 meters that links Toyama and Nagano prefectures. Read about its spectacular sights, including the caldera lake Mikurigaike and the powerful Kurobe Dam. Learn how to get to this famous nature area and things to do.\n\nSeventy percent of Japan\'s terrain is made up of mountains and hills. Thus, outdoor destinations are in abundance, and must-visit places are paradises for nature lovers.\n\nThe route has two starting points: Tateyama Station in Toyama and Ogizawa Station in Nagano. Visitors can go sightseeing from either point via the cable car, ropeway, or bus. Every spot along the journey is scattered with amazing sights to see. Some of them include Mikurigaike Pond, which beautifully reflects the mountains in its waters, and Kurobe Dam, the tallest dam in Japan! We suggest researching the places beforehand and double-checking the modes of transportation available.\n\nIn this article, we\'ll introduce these scenic spots along the Tateyama Kurobe Alpine Route and how to get to them.', E'["https://resources.matcha-jp.com/resize/720x2000/2020/04/27-102153.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/27-102151.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/27-102132.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/27-102130.webp"]'::jsonb, E'2020-05-16'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/5368', E'en', 16, E'Toyama Bay', E'Toyama Bay (富山湾, Toyama-wan) is a bay located on the northern shores of the Hokuriku region of Honshu, Japan on the Sea of Japan.\n\nThe bay borders Toyama and Ishikawa prefectures.The bay is known for the mirages on the horizon during the winter months and for being a spawning ground for the firefly squid.\n\nIt is also one of Japan\'s three largest bays.Parts of the bay are within the borders of the Noto Hantō Quasi-National Park.\n\nToyama shrimp are found in Toyama bay, which they are named after.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/11/15-41440.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/15-41441.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/15-41442.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/15-41443.webp"]'::jsonb, E'2017-12-28'::timestamptz, E'Toyama Bay', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Toyama_Bay'),
(E'https://matcha-jp.com/en/2728', E'en', 16, E'Toyama Prefectural Museum of Art and Design', E'Toyama Prefectural Museum of Art and Design (富山県美術館, Toyama-ken Bijutsukan) opened in Toyama, Toyama Prefecture, Japan in 2017, superseding and replacing the former Museum of Modern Art, Toyama (1981–2016).\n\nThe collection combines 20th- and 21st-century art with design, and includes works by Pablo Picasso, Joan Miró, and Munakata Shikō, as well as posters and chairs.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/30-221643.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/30-221644.webp","https://resources.matcha-jp.com/archive_files/jp/2016/09/e7a200f7d9e3e6690544bc9d1327eee9.webp","https://resources.matcha-jp.com/archive_files/jp/2016/09/b6ce0054c49f2f10562589227854beb6.webp"]'::jsonb, E'2016-10-19'::timestamptz, E'Toyama Prefectural Museum of Art and Design', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Toyama_Prefectural_Museum_of_Art_and_Design'),
(E'https://matcha-jp.com/en/7545', E'en', 17, E'Ishikawa Travel Guide: 14 Places to Visit, Fine Food, and Activities', E'Ishikawa Prefecture boasts traditional townscapes and a rich natural environment. Read on to learn about the fine cuisine, scenic places to visit, and cultural assets of Kanazawa, Noto, and Kaga Onsen in Ishikawa.\n\nIshikawa Prefecture is located in the Hokuriku Region. Following the debut of the Hokuriku Shinkansen, day trips from Tokyo to this prefecture have become popular.\n\nIshikawa is famous for its natural environment and culture, with a wide variety of sightseeing spots. It is also renowned for its fresh seafood, such as the crabs caught in the Japan Sea, and adorable Japanese confectionery.\n\nTraditional craftwork, namely lacquerware and gold leaf, is produced in Wajima City. For those hoping to experience fine cuisine and Japanese culture, Ishikawa is the place to visit.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/06/12-79333.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/12-79309.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/12-79310.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/12-79332.webp"]'::jsonb, E'2019-07-01'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/20689', E'en', 17, E'Kaga: 15 Things to Do For a Culture-Filled Experience', E'Kaga, located in Ishikawa prefecture, is known for its relaxing onsen towns, traditional crafts, and historical sites. In this article, we will introduce 12 exciting things to do to get the most out of your visit!\n\nKaga is a city located in Ishikawa Prefecture known for its serene hot spring towns, traditional crafts like pottery, and historical sites like Daishoji (an Edo period castle town).\n\nKaga holds a rich culture and history that attracts all types of visitors. Whether you’re a group of five or traveling solo, you will find an activity suited for you or your group.\n\nIf you’re searching for what to do and where to go, look no further, we’ve got you covered! Choose from one of these activities in Kaga and create memories you’ll be talking about years after.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/07/23-189299.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/23-189317.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/23-189318.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/23-189319.webp"]'::jsonb, E'2024-07-23'::timestamptz, null, null, null)
